const { chromium } = require('/Users/yuvalt/personal/visual-renderer/bench/versus-browser/tooling/node_modules/playwright');
const path = require('path');

const url = 'file://' + path.resolve(__dirname, 'card.html');
const sizes = [
  ['square', 1080, 1080],
  ['landscape', 1920, 1080],
  ['story', 1080, 1920],
];

(async () => {
  const browser = await chromium.launch();
  let bad = 0;
  for (const [name, width, height] of sizes) {
    const page = await browser.newPage({ viewport: { width, height } });
    await page.goto(url);
    await page.evaluate(() => document.fonts.ready);
    const report = await page.evaluate(({ width, height }) => {
      const pad = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--pad'));
      const out = { issues: [], boxes: [] };
      const sel = ['.header', '.header img', '.event-name', '.avatar', '.avatar img',
                   '.who .nm', '.who .rl', '.title', '.meta', '.btn', '.footer'];
      for (const s of sel) {
        const el = document.querySelector(s);
        if (!el) { out.issues.push('MISSING ' + s); continue; }
        const r = el.getBoundingClientRect();
        out.boxes.push({ s, x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1) });
        if (r.left < pad - 1.5 || r.top < pad - 1.5 || r.right > width - pad + 1.5 || r.bottom > height - pad + 1.5) {
          out.issues.push(`OUT-OF-SAFE-AREA ${s}: [${r.left.toFixed(1)}, ${r.top.toFixed(1)}, ${r.right.toFixed(1)}, ${r.bottom.toFixed(1)}] safe=[${pad}, ${pad}, ${width - pad}, ${height - pad}]`);
        }
        if (el.scrollWidth > el.clientWidth + 1 && getComputedStyle(el).overflow !== 'visible') {
          out.issues.push(`CLIPPED-X ${s}`);
        }
      }
      // circle check
      const img = document.querySelector('.avatar img');
      const ir = img.getBoundingClientRect();
      if (Math.abs(ir.width - ir.height) > 0.5) out.issues.push(`AVATAR-NOT-SQUARE ${ir.width}x${ir.height}`);
      const br = getComputedStyle(img).borderRadius;
      if (!br.includes('50%') && parseFloat(br) < ir.width / 2 - 1) out.issues.push('AVATAR-NOT-CIRCLE ' + br);
      // doc overflow
      const de = document.documentElement;
      if (de.scrollWidth > width + 1 || de.scrollHeight > height + 1) {
        out.issues.push(`PAGE-OVERFLOW ${de.scrollWidth}x${de.scrollHeight} vs ${width}x${height}`);
      }
      // text truncation check (any element whose scroll size exceeds client)
      document.querySelectorAll('.title, .nm, .rl, .meta, .btn, .event-name').forEach(el => {
        if (el.scrollHeight > el.clientHeight + 1) out.issues.push('TEXT-CLIPPED-Y ' + el.className);
      });
      // pairwise overlap of text blocks
      const items = [...document.querySelectorAll('.title, .who, .avatar, .meta, .btn, .header')];
      for (let i = 0; i < items.length; i++) for (let j = i + 1; j < items.length; j++) {
        const a = items[i].getBoundingClientRect(), b = items[j].getBoundingClientRect();
        if (items[i].contains(items[j]) || items[j].contains(items[i])) continue;
        const ox = Math.min(a.right, b.right) - Math.max(a.left, b.left);
        const oy = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
        if (ox > 2 && oy > 2) out.issues.push(`OVERLAP ${items[i].className} <> ${items[j].className} (${ox.toFixed(1)}x${oy.toFixed(1)})`);
      }
      return out;
    }, { width, height });

    console.log(`\n=== ${name} ${width}x${height} ===`);
    for (const b of report.boxes) console.log(`   ${b.s.padEnd(14)} x=${String(b.x).padStart(7)} y=${String(b.y).padStart(7)} w=${String(b.w).padStart(7)} h=${String(b.h).padStart(6)}`);
    if (report.issues.length) { bad++; console.log('  ISSUES:'); report.issues.forEach(i => console.log('   ! ' + i)); }
    else console.log('  OK — no issues');
    await page.close();
  }
  await browser.close();
  console.log(bad ? `\n${bad} size(s) with issues` : '\nALL CLEAN');
})();

